<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reçu #<?= (int)$payment['id'] ?> — Horizon Sportif de Bir El Hafey</title><style>body{font:15px Arial,sans-serif;color:#222;background:#f5f6f2;margin:0}.receipt{max-width:600px;background:#fff;margin:40px auto;padding:40px;border:1px solid #ddd}h1{font-size:24px}h2{margin-top:40px;font-size:18px}dl{display:grid;grid-template-columns:1fr 1fr;gap:16px}dt{color:#666}dd{margin:0;text-align:right;font-weight:bold}.total{border-top:1px solid #ddd;padding-top:20px;font-size:20px}.note{font-size:12px;color:#666;line-height:1.6;margin-top:40px}button,a{display:inline-block;margin:20px 10px 0 0;padding:10px;color:#222}button{cursor:pointer}@media print{body{background:#fff}.receipt{border:0;margin:0 auto}.actions{display:none}}</style></head><body><main class="receipt"><h1>HORIZON SPORTIF DE BIR EL HAFEY</h1><p>Reçu d'encaissement</p><h2>Reçu n° <?= (int)$payment['id'] ?></h2><dl><dt>Date</dt><dd><?= e(date('d/m/Y à H:i',strtotime($payment['paid_at']))) ?></dd><dt>Membre</dt><dd><?= e($payment['first_name'].' '.$payment['last_name']) ?></dd><dt>Carte</dt><dd><?= e($payment['card_number'] ?: '—') ?></dd><dt>Formule</dt><dd><?= e($payment['plan'] ?: '—') ?></dd><dt>Paiement</dt><dd><?= e(ucfirst($payment['method'])) ?></dd><dt class="total">Montant reçu</dt><dd class="total"><?= e(dt($payment['amount'])) ?></dd></dl><p class="note">Ce document est un justificatif d'encaissement, pas une facture fiscale. TVA et timbre fiscal ne sont pas calculés.</p><div class="actions"><button onclick="window.print()">Imprimer / enregistrer en PDF</button><a href="index.php?page=payments">Retour à la caisse</a></div></main></body></html>
